import{_ as a,o as n,c as e,a2 as p}from"./chunks/framework.DiFhKIuW.js";const b=JSON.parse('{"title":"前端模块化","description":"","frontmatter":{},"headers":[],"relativePath":"Engineering/Module.md","filePath":"Engineering/Module.md","lastUpdated":1782268044000}'),l={name:"Engineering/Module.md"};function i(r,s,o,c,d,t){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="前端模块化" tabindex="-1">前端模块化 <a class="header-anchor" href="#前端模块化" aria-label="Permalink to &quot;前端模块化&quot;">​</a></h1><p>在NodeJS之前，由于没有过于复杂的开发场景，前端是不存在模块化的。NodeJS诞生之后，它使用<code>CommonJS</code>的模块化规范。从此，js模块化开始快速发展。</p><p>模块化的开发方式可以提供代码复用率，方便进行代码的管理。通常来说，<strong>一个文件就是一个模块，有自己的作用域，只向外暴露特定的变量和函数</strong>。</p><h2 id="commonjs" tabindex="-1">CommonJS <a class="header-anchor" href="#commonjs" aria-label="Permalink to &quot;CommonJS&quot;">​</a></h2><p>NodeJS是<code>CommonJS</code>规范的主要实践者，它有四个重要的环境变量为模块化的实现提供支持：<code>module</code>、<code>exports</code>、<code>require</code>、<code>global</code>。</p><p>每个文件就是一个模块，有自己的作用域。在一个文件里面定义的变量、函数、类，都是私有的，对其他文件不可见。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// example.js</span></span>
<span class="line"><span>var x = 5;</span></span>
<span class="line"><span>var addX = function (value) {</span></span>
<span class="line"><span>  return value + x;</span></span>
<span class="line"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>上面代码中，变量<code>x</code>和函数<code>addX</code>，是当前文件<code>example.js</code>私有的，其他文件不可见。</p><p>如果想在多个文件分享变量，必须定义为<code>global</code>对象的属性。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global.warning = true;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>上面代码的<code>warning</code>变量，可以被所有文件读取。当然，这样写法是不推荐的。</p><p>CommonJS规范规定，每个模块内部，<code>module</code>变量代表当前模块。这个变量是一个对象，它的<code>exports</code>属性（即<code>module.exports</code>）是对外的接口。加载某个模块，其实是加载该模块的<code>module.exports</code>属性。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var x = 5;</span></span>
<span class="line"><span>var addX = function (value) {</span></span>
<span class="line"><span>  return value + x;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>module.exports.x = x;</span></span>
<span class="line"><span>module.exports.addX = addX;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>上面代码通过<code>module.exports</code>输出变量<code>x</code>和函数<code>addX</code>。</p><p><code>require</code>方法用于加载模块。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var example = require(&#39;./example.js&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>console.log(example.x); // 5</span></span>
<span class="line"><span>console.log(example.addX(1)); // 6</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>CommonJS模块的特点如下。</p><ul><li>所有代码都运行在模块作用域，不会污染全局作用域。</li><li>模块可以多次加载，但是只会在第一次加载时运行一次，然后运行结果就被缓存了，以后再加载，就直接读取缓存结果。要想让模块再次运行，必须清除缓存。</li><li>模块加载的顺序，按照其在代码中出现的顺序。</li></ul><h3 id="module对象" tabindex="-1">Module对象 <a class="header-anchor" href="#module对象" aria-label="Permalink to &quot;Module对象&quot;">​</a></h3><p>Node内部提供一个Module构建函数。所有模块都是Module的实例。</p><p>每个模块内部，都有一个<code>module</code>对象，代表当前模块。它有以下属性。</p><ul><li><code>module.id</code> 模块的识别符，通常是带有绝对路径的模块文件名。</li><li><code>module.filename</code> 模块的文件名，带有绝对路径。</li><li><code>module.loaded</code> 返回一个布尔值，表示模块是否已经完成加载。</li><li><code>module.parent</code> 返回一个对象，表示调用该模块的模块。</li><li><code>module.children</code> 返回一个数组，表示该模块要用到的其他模块。</li><li><code>module.exports</code> 表示模块对外输出的值。</li></ul><p>如果在命令行下调用某个模块，比如node something.js，那么module.parent就是null。如果是在脚本之中调用，比如require(&#39;./something.js&#39;)，那么module.parent就是调用它的模块。利用这一点，可以判断当前模块是否为入口脚本。</p><h3 id="module-exports属性" tabindex="-1">module.exports属性 <a class="header-anchor" href="#module-exports属性" aria-label="Permalink to &quot;module.exports属性&quot;">​</a></h3><p>module.exports属性表示当前模块对外输出的接口，其他文件加载该模块，实际上就是读取module.exports变量。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var x = 5;</span></span>
<span class="line"><span>var addX = function (value) {</span></span>
<span class="line"><span>  return value + x;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>module.exports.x = x;</span></span>
<span class="line"><span>module.exports.addX = addX;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var example = require(&#39;./example.js&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>console.log(example.x); // 5</span></span>
<span class="line"><span>console.log(example.addX(1)); // 6</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="exports变量" tabindex="-1">exports变量 <a class="header-anchor" href="#exports变量" aria-label="Permalink to &quot;exports变量&quot;">​</a></h3><p>为了方便，Node为每个模块提供一个exports变量，指向module.exports。这等同在每个模块头部，有一行这样的命令。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var exports = module.exports;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>因此，在对外输出模块接口时，可以向exports对象添加方法。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exports.area = function (r) {</span></span>
<span class="line"><span>  return Math.PI * r * r;</span></span>
<span class="line"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>注意，因为<code>exports</code>持有的是<code>module.exports</code>的引用，所以，不能直接将exports变量指向一个值，因为这样等于切断了exports与module.exports的联系。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exports = function(x) {console.log(x)};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>上面这样的写法是无效的，因为exports不再指向module.exports了。</p><p>下面的写法也是无效的。因为也切段了<code>exports</code>对<code>module.exports</code>的引用</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exports.hello = function() {</span></span>
<span class="line"><span>  return &#39;hello&#39;;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>module.exports = &#39;Hello world&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>上面代码中，hello函数是无法对外输出的，因为module.exports被重新赋值了。</p><p>如果一个模块的对外接口，就是一个单一的值，不能使用exports输出，只能使用module.exports输出。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.exports = function (x){ console.log(x);};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="加载模式" tabindex="-1">加载模式 <a class="header-anchor" href="#加载模式" aria-label="Permalink to &quot;加载模式&quot;">​</a></h3><p>CommonJS规范加载模块是同步的，在输入时是先加载整个模块，生成一个对象，然后再从这个对象上面读取方法，这种加载称为“运行时加载”。也就是说，只有加载完成，才能执行后面的操作。由于Node.js主要用于服务器编程，模块文件一般都已经存在于本地硬盘，读取非常快，所以这样做不会有问题。</p><h3 id="加载机制" tabindex="-1">加载机制 <a class="header-anchor" href="#加载机制" aria-label="Permalink to &quot;加载机制&quot;">​</a></h3><p>CommonJS模块的加载机制是，输入的是被输出的值的拷贝。也就是说，一旦输出一个值，模块内部的变化就影响不到这个值。</p><p>下面是一个模块文件<code>lib.js</code>。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// lib.js</span></span>
<span class="line"><span>var counter = 3;</span></span>
<span class="line"><span>function incCounter() {</span></span>
<span class="line"><span>  counter++;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>module.exports = {</span></span>
<span class="line"><span>  counter: counter,</span></span>
<span class="line"><span>  incCounter: incCounter,</span></span>
<span class="line"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>上面代码输出内部变量<code>counter</code>和改写这个变量的内部方法<code>incCounter</code>。</p><p>然后，加载上面的模块。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// main.js</span></span>
<span class="line"><span>var counter = require(&#39;./lib&#39;).counter;</span></span>
<span class="line"><span>var incCounter = require(&#39;./lib&#39;).incCounter;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>console.log(counter);  // 3</span></span>
<span class="line"><span>incCounter();</span></span>
<span class="line"><span>console.log(counter); // 3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>上面代码说明，<code>counter</code>输出以后，<code>lib.js</code>模块内部的变化就影响不到<code>counter</code>了。</p><h2 id="amd规范" tabindex="-1">AMD规范 <a class="header-anchor" href="#amd规范" aria-label="Permalink to &quot;AMD规范&quot;">​</a></h2><p>AMD规范是非同步加载模块，允许指定回调函数。浏览器环境下，要从服务器端加载模块，就必须采用非同步模式，因此浏览器端一般采用AMD规范。</p><p>AMD规范使用define方法定义模块，如果我们定义的模块本身也依赖其他模块,那就需要将它们放在[]中作为define()的第一参数。下面就是一个例子：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define([&#39;package/lib&#39;], function(lib){</span></span>
<span class="line"><span>  function foo(){</span></span>
<span class="line"><span>lib.log(&#39;hello world!&#39;);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  return {</span></span>
<span class="line"><span>foo: foo</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>引用模块的时候，我们将模块名放在[]中作为reqiure()的第一参数；所有依赖这个模块的语句，都定义在一个回调函数中，等到加载完成之后，这个回调函数才会运行。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 引用模块，将模块放在[]内</span></span>
<span class="line"><span>require([&#39;jquery&#39;, &#39;math&#39;],function($, math){</span></span>
<span class="line"><span>  var sum = math.add(10,20);</span></span>
<span class="line"><span>  $(&quot;#sum&quot;).html(sum);</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="require" tabindex="-1">require <a class="header-anchor" href="#require" aria-label="Permalink to &quot;require&quot;">​</a></h2><h3 id="加载规则" tabindex="-1">加载规则 <a class="header-anchor" href="#加载规则" aria-label="Permalink to &quot;加载规则&quot;">​</a></h3><p>require命令用于加载文件，后缀名默认为.js。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var foo = require(&#39;foo&#39;);</span></span>
<span class="line"><span>//  等同于</span></span>
<span class="line"><span>var foo = require(&#39;foo.js&#39;);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>根据参数的不同格式，<code>require</code>命令去不同路径寻找模块文件。</p><ol><li><p>如果参数字符串以“/”开头，则表示加载的是一个位于绝对路径的模块文件。比如，<code>require(&#39;/home/marco/foo.js&#39;)</code>将加载<code>/home/marco/foo.js</code>。</p></li><li><p>如果参数字符串以“./”开头，则表示加载的是一个位于相对路径（跟当前执行脚本的位置相比）的模块文件。比如，<code>require(&#39;./circle&#39;)</code>将加载当前脚本同一目录的<code>circle.js</code>。</p></li><li><p>如果参数字符串不以“./“或”/“开头，则表示加载的是一个默认提供的核心模块（位于Node的系统安装目录中），或者一个位于各级node_modules目录的已安装模块（全局安装或局部安装）。</p></li></ol><p>举例来说，脚本<code>/home/user/projects/foo.js</code>执行了<code>require(&#39;bar.js&#39;)</code>命令，Node会依次搜索以下文件。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/usr/local/lib/node/bar.js</span></span>
<span class="line"><span>/home/user/projects/node_modules/bar.js</span></span>
<span class="line"><span>/home/user/node_modules/bar.js</span></span>
<span class="line"><span>/home/node_modules/bar.js</span></span>
<span class="line"><span>/node_modules/bar.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ol start="4"><li><p>如果参数字符串不以“./“或”/“开头，而且是一个路径，比如require(&#39;example-module/path/to/file&#39;)，则将先找到example-module的位置，然后再以它为参数，找到后续路径。</p></li><li><p>如果指定的模块文件没有发现，Node会尝试为文件名添加.js、.json、.node后，再去搜索。.js件会以文本格式的JavaScript脚本文件解析，.json文件会以JSON格式的文本文件解析，.node文件会以编译后的二进制文件解析。</p></li><li><p>如果想得到require命令加载的确切文件名，使用require.resolve()方法。</p></li></ol><h3 id="目录加载规则" tabindex="-1">目录加载规则 <a class="header-anchor" href="#目录加载规则" aria-label="Permalink to &quot;目录加载规则&quot;">​</a></h3><p>在package.json文件中，将入口文件写入main字段。让require方法可以通过这个入口文件，加载整个目录下面是一个例子。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// package.json</span></span>
<span class="line"><span>{ </span></span>
<span class="line"><span>&quot;name&quot; : &quot;some-library&quot;,</span></span>
<span class="line"><span>  &quot;main&quot; : &quot;./lib/some-library.js&quot; </span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>require发现参数字符串指向一个目录以后，会自动查看该目录的package.json文件，然后加载main字段指定的入口文件。如果package.json文件没有main字段，或者根本就没有package.json文件，则会加载该目录下的index.js文件或index.node文件。</p><h3 id="模块的缓存" tabindex="-1">模块的缓存 <a class="header-anchor" href="#模块的缓存" aria-label="Permalink to &quot;模块的缓存&quot;">​</a></h3><p>第一次加载某个模块时，Node会缓存该模块。以后再加载该模块，就直接从缓存取出该模块的module.exports属性。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>require(&#39;./example.js&#39;);</span></span>
<span class="line"><span>require(&#39;./example.js&#39;).message = &quot;hello&quot;;</span></span>
<span class="line"><span>require(&#39;./example.js&#39;).message</span></span>
<span class="line"><span>// &quot;hello&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>连续三次使用require命令，加载同一个模块。第二次加载的时候，为输出的对象添加了一个message属性。但是第三次加载的时候，这个message属性依然存在，这就证明require命令并没有重新加载模块文件，而是输出了缓存。</p><p>如果想要多次执行某个模块，可以让该模块输出一个函数，然后每次require这个模块的时候，重新执行一下输出的函数。</p><p>require函数及其辅助方法主要如下。</p><ul><li>require(): 加载外部模块</li><li>require.resolve()：将模块名解析到一个绝对路径</li><li>require.main：指向主模块</li><li>require.cache：指向所有缓存的模块</li><li>require.extensions：根据文件的后缀名，调用不同的执行函数</li></ul><h2 id="cmd" tabindex="-1">CMD <a class="header-anchor" href="#cmd" aria-label="Permalink to &quot;CMD&quot;">​</a></h2><p>AMD的实现者require.js在申明依赖的模块时，会在第一时间加载并执行模块内的代码：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define([&quot;a&quot;, &quot;b&quot;, &quot;c&quot;, &quot;d&quot;, &quot;e&quot;, &quot;f&quot;], function(a, b, c, d, e, f) { </span></span>
<span class="line"><span>    // 等于在最前面声明并初始化了要用到的所有模块</span></span>
<span class="line"><span>if (false) {</span></span>
<span class="line"><span>  // 即便没用到某个模块 b，但 b 还是提前执行了。**这就CMD要优化的地方**</span></span>
<span class="line"><span>  b.foo()</span></span>
<span class="line"><span>} </span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>CMD是另一种js模块化方案，它与AMD很类似，不同点在于：AMD推崇依赖前置、提前执行，CMD推崇依赖就近、延迟执行。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define(function (require, exports, module){</span></span>
<span class="line"><span>  var someModule = require(&quot;someModule&quot;);</span></span>
<span class="line"><span>  var anotherModule = require(&quot;anotherModule&quot;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  someModule.doTehAwesome();</span></span>
<span class="line"><span>  anotherModule.doMoarAwesome();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  exports.asplode = function (){</span></span>
<span class="line"><span>someModule.doTehAwesome();</span></span>
<span class="line"><span>anotherModule.doMoarAwesome();</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="umd" tabindex="-1">UMD <a class="header-anchor" href="#umd" aria-label="Permalink to &quot;UMD&quot;">​</a></h2><p>umd是一种思想，就是一种兼容 commonjs,AMD,CMD 的兼容写法，define.amd / define.cmd / module 等判断当前支持什么方式，</p><p>UMD先判断支持Node.js的模块（exports）是否存在，存在则使用Node.js模块模式。再判断是否支持AMD（define是否存在），存在则使用AMD方式加载模块。都不行就挂载到 window 全局对象上面去</p><p>(function (root, factory) { if (typeof define === &#39;function&#39; &amp;&amp; (define.amd || define.cmd)) { //AMD,CMD define([&#39;b&#39;], function(b){ return (root.returnExportsGlobal = factory(b)) }); } else if (typeof module === &#39;object&#39; &amp;&amp; module.exports) { //Node, CommonJS之类的 module.exports = factory(require(&#39;b&#39;)); } else { //公开暴露给全局对象 root.returnExports = factory(root.b); } }(this, function (b) { return {}; }));</p><h2 id="es6-module" tabindex="-1">ES6 Module <a class="header-anchor" href="#es6-module" aria-label="Permalink to &quot;ES6 Module&quot;">​</a></h2><p>ES6 在语言标准的层面上，实现了模块功能，而且实现得相当简单，旨在成为浏览器和服务器通用的模块解决方案。其模块功能主要由两个命令构成：<code>export</code>和<code>import</code>。<code>export</code>命令用于规定模块的对外接口，<code>import</code>命令用于输入其他模块提供的功能。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/** 定义模块 math.js **/</span></span>
<span class="line"><span>var basicNum = 0;</span></span>
<span class="line"><span>var add = function (a, b) {</span></span>
<span class="line"><span>return a + b;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>export { basicNum, add };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/** 引用模块 **/</span></span>
<span class="line"><span>import { basicNum, add } from &#39;./math&#39;;</span></span>
<span class="line"><span>function test(ele) {</span></span>
<span class="line"><span>ele.textContent = add(99 + basicNum);</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>ES6还提供了export default命令，为模块指定默认输出，对应的import语句不需要使用大括号。这也更趋近于ADM的引用写法。</p><p>ES6 模块的特征：</p><ul><li>严格模式：ES6 的模块自动采用严格模式</li><li>import read-only特性： import的属性是只读的，不能赋值，类似于const的特性</li><li>export/import提升： import/export必须位于模块顶级，不能位于作用域内；其次对于模块内的import/export会提升到模块顶部，这是在编译阶段完成的</li></ul><h2 id="加载机制-1" tabindex="-1">加载机制 <a class="header-anchor" href="#加载机制-1" aria-label="Permalink to &quot;加载机制&quot;">​</a></h2><p>ES6 模块的运行机制与 CommonJS 不一样。ES6 模块不是对象，而是通过 export 命令显式指定输出的代码，import时采用静态命令的形式。JS 引擎对脚本静态分析的时候，遇到模块加载命令import，就会生成一个<strong>只读引用</strong>。等到脚本真正执行时，再根据这个只读引用，到被加载的那个模块里面去取值。模块内部引用的变化，会反应在外部。</p><p>在import时可以指定加载某个输出值，而不是加载整个模块，这种加载称为“编译时加载”。在编译时就引入模块代码，而不是在代码运行时加载，所以无法实现条件加载。也正因为这个，使得静态分析成为可能。</p><h2 id="参考文档" tabindex="-1">参考文档： <a class="header-anchor" href="#参考文档" aria-label="Permalink to &quot;参考文档：&quot;">​</a></h2><ol><li><a href="https://javascript.ruanyifeng.com/nodejs/module.html" target="_blank" rel="noreferrer">CommonJS规范</a></li><li>[<a href="https://www.cnblogs.com/chenwenhao/p/12153332.html" target="_blank" rel="noreferrer">前端模块化——彻底搞懂AMD、CMD、ESM和CommonJS</a>]</li></ol>`,96)])])}const m=a(l,[["render",i]]);export{b as __pageData,m as default};
